research_cards=''.join(card(a,b,ext(u),label='Explore topic',eyebrow='Research area') for a,b,u in TOPICS)
body=f'''<div class="page-body"><section><div class="wrap"><div class="section-head"><div><div class="eyebrow">Methods & applications</div><h2>Explore research areas</h2></div><p>IEOR research spans mathematical methods and applications across industries and services.</p></div><div class="grid grid-3">{research_cards}</div></div></section><section class="blue-section"><div class="wrap split"><div class="image-frame"><img src="/assets/research.jpeg" alt="Participants at an IEOR research workshop" loading="lazy"></div><div><div class="eyebrow">Work and people</div><h2>Follow the research.</h2><p>Research topics connect to faculty interests, publications, student projects and computational resources. Some thesis files are available only on the IIT Bombay network.</p>{linklist([('Faculty and research interests',ext('/people/faculty')),('Publications',ext('/research/pub')),('Student projects',ext('/research/student_projects')),('Computational resources',ext('/research/comp'))])}</div></div></section><section><div class="wrap mini-grid"><div><h2>Collaborate with IEOR</h2><p>IEOR works with industry and other organizations through research, consulting, student projects and continuing education.</p><a class="button button-blue" href="/opportunities/">Explore opportunities</a></div><div><h2>Centers and labs</h2>{linklist([('FedEx ALFA',ext('/fedexalfa/')),('TCAAI at IIT Bombay','https://www.tcaai.iitb.ac.in/')])}</div></div></section></div>'''
write('research',page('Research','Methods and applications in optimization, uncertainty, simulation, learning and systems.',body,'/research/'))

# People
body=f'''<div class="page-body"><section><div class="wrap mini-grid"><div><div class="eyebrow">The community</div><h2>Find the people behind the work.</h2><p>IEOR brings together faculty, postdoctoral researchers, students and staff. Browse the maintained directories for current profiles and research interests.</p><a class="button button-blue" href="{ext('/people/faculty')}">Faculty directory</a></div><div class="image-frame"><img src="/assets/community.jpg" alt="IEOR students and faculty gathered at the 2026 convocation" loading="lazy"></div></div></section><section><div class="wrap"><div class="section-head"><div><div class="eyebrow">Directories</div><h2>Explore by role</h2></div></div><div class="grid grid-3">{card('Faculty','Research interests, profiles and contact information.',ext('/people/faculty'),eyebrow='Research & teaching')}{card('Students','Current student directory and representatives.',ext('/students'),eyebrow='Community')}{card('Staff & postdocs','Office staff and postdoctoral fellows.',ext('/people/office'),eyebrow='Support & research')}</div></div></section><section><div class="wrap mini-grid"><div><h2>Alumni</h2><p>Graduates connect the department across research, industry and public service. Explore the existing alumni network and ways to contribute.</p><a class="button button-blue" href="{ext('/node/3911')}">Alumni engagement</a></div><div><h2>Additional directories</h2>{linklist([('Postdoctoral fellows',ext('/people/postdocs')),('Student representatives',ext('/people/student_reps_26')),('Faculty advisors',ext('/people/facultyadvisors')),('Institute award winners',ext('/people/awards'))])}</div></div></section></div>'''
